  "slides": [
    {
      "title": "Your 1-on-1s Are Probably Status Meetings in Disguise",
      "body": "If your team member is mostly giving you project updates, something has gone wrong. Here's how to fix it.",
      "isCover": true
    },
    {
      "title": "The Purpose Is the Relationship, Not the Report",
      "body": "One-on-ones exist so your direct report feels heard, supported, and unblocked — not so you can track what they finished last week.",
      "isCover": false
    },
    {
      "title": "Stop Asking 'What Did You Work On?'",
      "body": "That question belongs in a standup. Instead ask: 'What's been hardest this week?' or 'What do you need from me right now?'",
      "isCover": false
    },
    {
      "title": "Let Them Set the Agenda",
      "body": "Ask your report to send two or three topics before the meeting. It signals that the time belongs to them — and you show up prepared to help.",
      "isCover": false
    },
    {
      "title": "Your Job Is to Listen, Then Remove Obstacles",
      "body": "Resist the urge to fill silence or jump to solutions. Ask a follow-up question first. The real issue is rarely the first thing they mention.",
      "isCover": false
    },
    {
      "title": "Keep a Shared Running Doc",
      "body": "One living document with both your names on it. Topics, decisions, and commitments go there so nothing falls through the cracks between meetings.",
      "isCover": false
    },
    {
      "title": "Save This and Run a Better 1-on-1 This Week",
      "body": "Pick one question from slide 3, let your report set the agenda, and listen before you advise. That single shift changes everything.",
      "isCover": true
    }
  ]
}

{
  "title": "Onboarding Your First Operations Hire",
  "seriesTag": "Ops Playbook",
  "brand": {
    "apply": true,
    "paper": "#0A1628",
    "ink": "#F5F0E8",
    "accent": "#C8F400",
    "headline": "editorial",
    "body": "clean"
  },
  "slides": [
    {
      "title": "Your First Ops Hire Will Make or Break Your Scaling",
      "body": "Hiring for operations is the highest-leverage move an early team can make — if you onboard them right. Here's how.",
      "isCover": true
    },
    {
      "title": "Hire for Systems Thinking, Not Just Experience",
      "body": "Your first ops hire needs to build the plane while flying it. Look for people who instinctively document, automate, and simplify — not just execute.",
      "isCover": false
    },
    {
      "title": "Give Them a 30-Day Listening Tour",
      "body": "Before they fix anything, they should map everything. Have them shadow every team, audit every workflow, and hold their recommendations until week five.",
      "isCover": false
    },
    {
      "title": "Define Their North Star Metric on Day One",
      "body": "Ops without a clear success metric drifts into busywork. Agree upfront: are they reducing cost, increasing throughput, or cutting time-to-close? One thing first.",
      "isCover": false
    },
    {
      "title": "Grant Access Before You Need To",
      "body": "Slow access requests kill momentum. Pre-provision tools, accounts, and documentation on day one. Trust them with the keys — that's why you hired them.",
      "isCover": false
    },
    {
      "title": "Schedule a Weekly Ops Review From Week Two",
      "body": "A standing 30-minute sync keeps priorities aligned and surfaces blockers early. This ritual compounds — the best ops leaders will eventually own this meeting.",
      "isCover": false
    },
    {
      "title": "Save This Before Your Next Ops Hire",
      "body": "Screenshot this carousel and share it with your founding team. A strong onboarding sets your ops hire — and your whole company — up to scale.",
      "isCover": true
    }
  ]
}

{
  "title": "Deep Work Doesn't Need 4 Hours",
  "seriesTag": "Myth Busted",
  "brand": {
    "apply": false,
    "paper": "#EFE9DA",
    "ink": "#212B21",
    "accent": "#C08A28",
    "headline": "editorial",
    "body": "clean"
  },
  "slides": [
    {
      "title": "You Don't Need a 4-Hour Block to Do Deep Work",
      "body": "Most knowledge workers believe deep focus is impossible without a half-day of silence. That belief is quietly destroying your productivity. Let's break it down.",
      "isCover": true
    },
    {
      "title": "The Myth: Deep Work = Long, Uninterrupted Time",
      "body": "The idea that deep work requires 4+ hour blocks comes from a misreading of Cal Newport's research. It describes an ideal — not a requirement.",
      "isCover": false
    },
    {
      "title": "The Reality: Your Brain Can't Sustain 4 Hours Anyway",
      "body": "Cognitive performance peaks at 90–120 minutes, then drops sharply. Pushing through doesn't create depth — it creates exhaustion and diminishing returns.",
      "isCover": false
    },
    {
      "title": "Even 45 Minutes Done Right Counts as Deep Work",
      "body": "Deep work is defined by intensity and intentionality, not duration. A focused 45-minute session with a clear goal outperforms a distracted 3-hour stretch every time.",
      "isCover": false
    },
    {
      "title": "The Real Enemy Isn't a Short Schedule — It's Context Switching",
      "body": "What kills deep work is toggling between tasks, not the clock. Protect a single-threaded focus window, however long you have, and you're doing it right.",
      "isCover": false
    },
    {
      "title": "High Performers Use Shorter, Stacked Sessions",
      "body": "Many elite researchers and writers work in 60–90 minute focused sprints with deliberate breaks in between. Frequency builds the skill. Duration is just the container.",
      "isCover": false
    },
    {
      "title": "Start Your Next Deep Work Session Today — Not When Your Calendar Clears",
      "body": "Block 60 minutes. Close the tabs. Pick one output. That's it. Save this post so you remember: depth is a practice, not a perfect schedule.",
      "isCover": true
    }
  ]
}

